INSERT INTO `artikel` (`id`, `judul`, `isi`, `gambar`, `tanggal`) VALUES
(1, 'Dokter Syok: 70% Pasien Infeksi Menular Seksual di Bawah 25 Tahun Tidak Sadar Tertular, Berikut Langkah Pencegahan dari Dokter Spesialis', '<p><em>(Ditinjau oleh: DR. dr. Mohammad Arief EL Habibie, MSM., ISQUA &ndash; Dokter Konsultan Infeksi Menular Seksual)</em></p>\r\n<p><strong>Data yang Mengkhawatirkan</strong></p>\r\n<p>Berdasarkan laporan terbaru&nbsp;<strong>Kementerian Kesehatan RI (2024)</strong>,&nbsp;<strong>70% pasien Infeksi Menular Seksual (IMS)</strong>&nbsp;berusia di bawah 25 tahun tidak menyadari bahwa mereka telah tertular.&nbsp;<strong>DR. dr. Mohammad Arief EL Habibie</strong>&nbsp;mengungkapkan keprihatinannya:<br><em>\"Banyak pasien muda datang ke klinik dengan gejala parah karena mengira penyakitnya hanya iritasi biasa. Mereka terkejut saat tahu sudah tertular IMS berbulan-bulan sebelumnya.\"</em></p>\r\n<p><strong>Mengapa Generasi Muda Tidak Sadar Tertular?</strong></p>\r\n<p><strong>1. Gejala yang Tidak Khas</strong></p>\r\n<ul>\r\n<li>\r\n<p><strong>Klamidia &amp; Gonore</strong>: 50% kasus tidak menunjukkan gejala awal.</p>\r\n</li>\r\n<li>\r\n<p><strong>Herpes Genital</strong>: Gejala bisa mirip dengan iritasi kulit biasa.</p>\r\n</li>\r\n<li>\r\n<p><strong>HPV</strong>: Kutil kelamin sering dianggap jerawat atau alergi.</p>\r\n</li>\r\n</ul>\r\n<p><strong>2. Kurangnya Edukasi Seksual</strong></p>\r\n<ul>\r\n<li>\r\n<p>Survei&nbsp;<strong>DKT Indonesia (2024)</strong>&nbsp;menunjukkan:</p>\r\n<ul>\r\n<li>\r\n<p>Hanya&nbsp;<strong>30% remaja</strong>&nbsp;yang tahu cara penularan IMS.</p>\r\n</li>\r\n<li>\r\n<p><strong>65%</strong>&nbsp;mengira IMS hanya menular melalui hubungan seks vaginal.</p>\r\n</li>\r\n</ul>\r\n</li>\r\n</ul>\r\n<p><strong>3. Stigma dan Rasa Malu</strong></p>\r\n<ul>\r\n<li>\r\n<p>Banyak pasien menunda pemeriksaan karena takut dihakimi.</p>\r\n</li>\r\n<li>\r\n<p><strong>Fenomena \"Dr. Google\"</strong>: Self-diagnosis yang sering salah.</p>\r\n</li>\r\n</ul>\r\n<p><strong>Tanda Halus yang Sering Diabaikan</strong></p>\r\n<ul>\r\n<li>\r\n<p><strong>Keputihan abnormal</strong>&nbsp;(berbau/berwarna kuning kehijauan)</p>\r\n</li>\r\n<li>\r\n<p><strong>Nyeri saat berhubungan</strong></p>\r\n</li>\r\n<li>\r\n<p><strong>Gatal di kemaluan yang tidak kunjung hilang</strong></p>\r\n</li>\r\n<li>\r\n<p><strong>Sakit tenggorokan kronis</strong>&nbsp;(akibat seks oral)</p>\r\n</li>\r\n</ul>\r\n<p><strong>DR. Arief Menekankan</strong>:<br><em>\"Jika Anda aktif secara seksual, lakukan tes IMS rutin meski tidak ada gejala. Ini adalah tanggung jawab kesehatan diri dan pasangan.\"</em></p>\r\n<p><strong>3 Langkah Pencegahan Efektif</strong> <strong>1. Skrining Rutin</strong></p>\r\n<ul>\r\n<li>\r\n<p><strong>Tes urine/sample darah</strong>&nbsp;setiap 6 bulan jika aktif secara seksual.</p>\r\n</li>\r\n<li>\r\n<p><strong>Vaksinasi HPV</strong>&nbsp;untuk pria dan wanita.</p>\r\n</li>\r\n</ul>\r\n<p><strong>2. Seks Aman</strong></p>\r\n<ul>\r\n<li>\r\n<p>Gunakan&nbsp;<strong>kondom</strong>&nbsp;secara konsisten (bahkan untuk oral seks).</p>\r\n</li>\r\n<li>\r\n<p>Hindari berganti pasangan seksual.</p>\r\n</li>\r\n</ul>\r\n<p><strong>3. Edukasi Dini</strong></p>\r\n<ul>\r\n<li>\r\n<p>Diskusikan kesehatan seksual dengan pasangan.</p>\r\n</li>\r\n<li>\r\n<p>Kenali gejala IMS sejak dini.</p>\r\n</li>\r\n</ul>\r\n<p><strong>Kisah Nyata (Anonim, 23 Tahun)</strong></p>\r\n<p><em>\"Aku kena gonore dari mantan pacar. Awalnya cuma anyang-anyangan, tapi ternyata sudah menular ke 2 pasangan berikutnya. Aku menyesal tidak tes IMS dulu.\"</em></p>\r\n<p><strong>Kapan Harus Tes IMS?</strong></p>\r\n<p>Segera periksa jika:<br>✅ Ada riwayat seks tanpa kondom<br>✅ Pasangan terdiagnosis IMS<br>✅ Muncul gejala tidak biasa di area genital</p>\r\n<p><strong>Hotline Kemenkes IMS</strong>: 0813-9851-5855 (Gratis &amp; Anonim)</p>\r\n<p><strong>Mitos vs Fakta</strong></p>\r\n<p>❌&nbsp;<em>\"IMS hanya menular melalui hubungan seks vaginal.\"</em><br>✅&nbsp;<strong>Fakta</strong>: Seks oral dan anal juga berisiko tinggi.</p>\r\n<p>❌&nbsp;<em>\"Pasangan yang terlihat sehat pasti bebas IMS.\"</em><br>✅&nbsp;<strong>Fakta</strong>: Banyak IMS tidak bergejala tetapi bisa menular.</p>\r\n<p><strong>Pesan Dokter</strong></p>\r\n<p><em>\"Jangan jadikan usia muda sebagai alasan untuk abai. IMS tidak pandang bulu. Lebih baik mencegah daripada menanggung konsekuensi seumur hidup.\"</em></p>\r\n<p><strong>Informasi Tambahan</strong>:</p>\r\n<ul>\r\n<li>\r\n<p>Biaya tes IMS dasar: Rp150.000&ndash;Rp500.000</p>\r\n</li>\r\n<li>\r\n<p>Hubungi Klinik Sanford untuk informasi lebih lanjut</p>\r\n</li>\r\n</ul>\r\n<p><em>(Artikel ini telah direview oleh DR. dr. Mohammad Arief EL Habibie, MSM., ISQUA)</em></p>', 'B1000058-Cover-Obat-untuk-Infeksi-Saluran-Kencing-scaled.jpg', '2025-04-20 09:15:08'),
(2, 'Dari Kencing Nanah sampai Mandul: Dampak Mengerikan Gonore yang Diabaikan', '<p data-start=\"173\" data-end=\"465\">Penyakit gonore atau yang lebih dikenal masyarakat dengan istilah <strong data-start=\"251\" data-end=\"270\">\"kencing nanah\"</strong> sering dianggap sepele. Namun, menurut dr. Mohammad Arief El Habibie, MSM., ISQUA, dampak infeksi menular seksual (IMS) ini bisa jauh lebih berbahaya bila tidak ditangani dengan cepat dan tepat.</p>\r\n<p data-start=\"467\" data-end=\"720\">\"Gonore bukan hanya menyebabkan keluarnya nanah dari kemaluan. Jika diabaikan, bisa merusak organ reproduksi, menyebabkan kemandulan, bahkan meningkatkan risiko infeksi sistemik,\" ujar dr. Arief dalam seminar kesehatan reproduksi di Medan, Sabtu (19/4).</p>\r\n<p><span><strong>Apa Itu Gonore?</strong></span></p>\r\n<p data-start=\"742\" data-end=\"987\">Gonore adalah infeksi bakteri <em data-start=\"772\" data-end=\"795\">Neisseria gonorrhoeae</em> yang menyebar melalui kontak seksual, baik vaginal, oral, maupun anal. Penyakit ini bisa menyerang pria dan wanita dari semua kelompok usia, namun <strong data-start=\"943\" data-end=\"970\">usia muda (15&ndash;29 tahun)</strong> paling berisiko.</p>\r\n<p data-start=\"989\" data-end=\"1040\">Bakteri gonore menyerang area lembab tubuh seperti:</p>\r\n<ul data-start=\"1041\" data-end=\"1143\">\r\n<li data-start=\"1041\" data-end=\"1067\">\r\n<p data-start=\"1043\" data-end=\"1067\">Uretra (saluran kencing)</p>\r\n</li>\r\n<li data-start=\"1068\" data-end=\"1091\">\r\n<p data-start=\"1070\" data-end=\"1091\">Leher rahim (serviks)</p>\r\n</li>\r\n<li data-start=\"1092\" data-end=\"1100\">\r\n<p data-start=\"1094\" data-end=\"1100\">Rektum</p>\r\n</li>\r\n<li data-start=\"1101\" data-end=\"1114\">\r\n<p data-start=\"1103\" data-end=\"1114\">Tenggorokan</p>\r\n</li>\r\n<li data-start=\"1115\" data-end=\"1143\">\r\n<p data-start=\"1117\" data-end=\"1143\">Mata (pada kasus tertentu)</p>\r\n</li>\r\n</ul>\r\n<p><span><strong>Gejala Awal Gonore yang Sering Diabaikan</strong></span></p>\r\n<p data-start=\"1190\" data-end=\"1391\">Gonore sering menunjukkan gejala ringan atau bahkan tanpa gejala sama sekali, terutama pada wanita. Ini membuat banyak orang tidak sadar telah terinfeksi.<br data-start=\"1344\" data-end=\"1347\">Beberapa tanda gonore yang patut diwaspadai:</p>\r\n<ul data-start=\"1392\" data-end=\"1642\">\r\n<li data-start=\"1392\" data-end=\"1447\">\r\n<p data-start=\"1394\" data-end=\"1447\">Keluarnya cairan seperti nanah dari penis atau vagina</p>\r\n</li>\r\n<li data-start=\"1448\" data-end=\"1476\">\r\n<p data-start=\"1450\" data-end=\"1476\">Nyeri saat buang air kecil</p>\r\n</li>\r\n<li data-start=\"1477\" data-end=\"1527\">\r\n<p data-start=\"1479\" data-end=\"1527\">Nyeri atau bengkak pada salah satu testis (pria)</p>\r\n</li>\r\n<li data-start=\"1528\" data-end=\"1569\">\r\n<p data-start=\"1530\" data-end=\"1569\">Perdarahan di luar siklus haid (wanita)</p>\r\n</li>\r\n<li data-start=\"1570\" data-end=\"1602\">\r\n<p data-start=\"1572\" data-end=\"1602\">Nyeri saat berhubungan seksual</p>\r\n</li>\r\n<li data-start=\"1603\" data-end=\"1642\">\r\n<p data-start=\"1605\" data-end=\"1642\">Sakit tenggorokan (pada infeksi oral)</p>\r\n</li>\r\n</ul>\r\n<p data-start=\"1644\" data-end=\"1753\">\"Karena gejalanya mirip infeksi biasa, banyak yang menunda berobat hingga infeksi menyebar,\" jelas dr. Arief.</p>\r\n<p><span><strong>Dampak Berbahaya Jika Gonore Tidak Diobati</strong></span></p>\r\n<p data-start=\"1802\" data-end=\"1865\">Jika gonore tidak segera diobati, risikonya bisa sangat serius:</p>\r\n<ul data-start=\"1866\" data-end=\"2441\">\r\n<li data-start=\"1866\" data-end=\"2034\">\r\n<p data-start=\"1868\" data-end=\"2034\"><strong data-start=\"1868\" data-end=\"1894\">Infertilitas (Mandul):</strong> Pada wanita, gonore bisa menyebabkan radang panggul yang merusak rahim dan saluran telur. Pada pria, infeksi bisa menyumbat saluran sperma.</p>\r\n</li>\r\n<li data-start=\"2035\" data-end=\"2164\">\r\n<p data-start=\"2037\" data-end=\"2164\"><strong data-start=\"2037\" data-end=\"2059\">Kehamilan Ektopik:</strong> Infeksi yang tidak tertangani meningkatkan risiko kehamilan di luar kandungan yang bisa mengancam nyawa.</p>\r\n</li>\r\n<li data-start=\"2165\" data-end=\"2322\">\r\n<p data-start=\"2167\" data-end=\"2322\"><strong data-start=\"2167\" data-end=\"2190\">Penyebaran Infeksi:</strong> Bakteri bisa masuk ke dalam darah atau sendi, menyebabkan kondisi berbahaya yang disebut <em data-start=\"2280\" data-end=\"2315\">disseminated gonococcal infection</em> (DGI).</p>\r\n</li>\r\n<li data-start=\"2323\" data-end=\"2441\">\r\n<p data-start=\"2325\" data-end=\"2441\"><strong data-start=\"2325\" data-end=\"2357\">Peningkatan Risiko HIV/AIDS:</strong> Gonore membuat lapisan pelindung alat kelamin rusak, memudahkan masuknya virus HIV.</p>\r\n</li>\r\n</ul>\r\n<p><span><strong>Gonore pada Bayi Baru Lahir</strong></span></p>\r\n<p data-start=\"2475\" data-end=\"2577\">Gonore juga bisa ditularkan dari ibu ke bayi saat persalinan. Bayi yang terinfeksi berisiko mengalami:</p>\r\n<ul data-start=\"2578\" data-end=\"2672\">\r\n<li data-start=\"2578\" data-end=\"2624\">\r\n<p data-start=\"2580\" data-end=\"2624\">Infeksi mata berat (konjungtivitis neonatal)</p>\r\n</li>\r\n<li data-start=\"2625\" data-end=\"2672\">\r\n<p data-start=\"2627\" data-end=\"2672\">Kebutaan permanen jika tidak segera ditangani</p>\r\n</li>\r\n</ul>\r\n<p data-start=\"2674\" data-end=\"2779\">\"Karena itu, semua ibu hamil disarankan skrining IMS, termasuk gonore, saat kehamilan,\" tambah dr. Arief.</p>\r\n<p><span><strong>Bagaimana Cara Menghindari Gonore?</strong></span></p>\r\n<p data-start=\"2820\" data-end=\"2875\">Untuk mencegah penularan gonore, dr. Arief menyarankan:</p>\r\n<ul data-start=\"2876\" data-end=\"3110\">\r\n<li data-start=\"2876\" data-end=\"2921\">\r\n<p data-start=\"2878\" data-end=\"2921\">Gunakan kondom saat berhubungan seksual</p>\r\n</li>\r\n<li data-start=\"2922\" data-end=\"2973\">\r\n<p data-start=\"2924\" data-end=\"2973\">Setia pada satu pasangan yang telah diperiksa</p>\r\n</li>\r\n<li data-start=\"2974\" data-end=\"3044\">\r\n<p data-start=\"2976\" data-end=\"3044\">Rutin melakukan skrining IMS, terutama jika aktif secara seksual</p>\r\n</li>\r\n<li data-start=\"3045\" data-end=\"3110\">\r\n<p data-start=\"3047\" data-end=\"3110\">Segera periksa ke dokter jika mengalami gejala mencurigakan</p>\r\n</li>\r\n</ul>\r\n<p data-start=\"3112\" data-end=\"3309\">Pengobatan gonore umumnya menggunakan antibiotik resep dokter. Namun, seiring waktu, muncul <strong data-start=\"3204\" data-end=\"3238\">strain gonore kebal antibiotik</strong> yang makin sulit diobati, sehingga <strong data-start=\"3274\" data-end=\"3308\">pencegahan menjadi kunci utama</strong>.</p>\r\n<p data-start=\"3313\" data-end=\"3476\">\"Jangan pernah remehkan kencing nanah. Segera periksa dan obati. Gonore bukan hanya soal rasa tidak nyaman, tapi soal masa depan reproduksi Anda,\" tutup dr. Arief.</p>', 'gonore .jfif', '2025-04-20 11:31:17'),
(3, 'Kapan Harus Memeriksakan Diri ke Klinik Penyakit Kelamin? Ini Panduan dari Dokter Spesialis', '<p><strong>Kapan Harus Memeriksakan Diri ke Klinik Penyakit Kelamin? Ini Panduan dari Dokter Spesialis</strong><br><em>(Oleh: Tim Medis Klinik Andrologi Terpadu - Ditinjau oleh: DR. dr. Mohammad Arief EL Habibie, MSM., ISQUA)</em></p>\r\n<p><strong>Pendahuluan</strong></p>\r\n<p>Penyakit kelamin atau Infeksi Menular Seksual (IMS) seringkali tidak menunjukkan gejala awal, namun dapat menyebabkan komplikasi serius jika tidak ditangani.<span>&nbsp;</span><strong>DR. dr. Mohammad Arief EL Habibie, MSM., ISQUA</strong>, Dokter Konsultan IMS menjelaskan:<br><em>\"80% pasien baru datang ke klinik saat kondisi sudah parah karena mengira gejala awalnya tidak berbahaya. Padahal deteksi dini adalah kunci kesembuhan.\"</em></p>\r\n<p>Berikut panduan lengkap kapan Anda harus memeriksakan diri ke klinik penyakit kelamin:</p>\r\n<p><strong>1. Saat Mengalami Gejala Ini</strong><strong>Pada Pria:</strong></p>\r\n<ul>\r\n<li>\r\n<p>Keluar nanah/kotoran dari penis (warna kuning, hijau, atau berdarah)</p>\r\n</li>\r\n<li>\r\n<p>Nyeri saat kencing atau berhubungan seksual</p>\r\n</li>\r\n<li>\r\n<p>Benjolan, luka, atau ruam di kemaluan</p>\r\n</li>\r\n<li>\r\n<p>Pembengkakan testis</p>\r\n</li>\r\n</ul>\r\n<p><strong>Pada Wanita:</strong></p>\r\n<ul>\r\n<li>\r\n<p>Keputihan abnormal (berbau, berwarna, atau gatal)</p>\r\n</li>\r\n<li>\r\n<p>Perdarahan di luar siklus menstruasi</p>\r\n</li>\r\n<li>\r\n<p>Nyeri panggul kronis</p>\r\n</li>\r\n<li>\r\n<p>Luka atau lepuh di area genital</p>\r\n</li>\r\n</ul>\r\n<p><strong>Catatan Dokter</strong>:<br><em>\"Gejala seperti keputihan atau anyang-anyangan sering dianggap biasa. Jika berlangsung &gt;2 minggu, wajib diperiksa!\"</em></p>\r\n<p><strong>2. Setelah Melakukan Aktivitas Berisiko</strong></p>\r\n<p>Segera periksa dalam 2 minggu jika:<br>✅ Berhubungan seks tanpa kondom dengan pasangan baru<br>✅ Pasangan terdiagnosis IMS<br>✅ Menggunakan narkoba suntik atau berbagi alat seks</p>\r\n<p><strong>Fakta Menarik</strong>:</p>\r\n<ul>\r\n<li>\r\n<p>Masa inkubasi IMS bervariasi:</p>\r\n<ul>\r\n<li>\r\n<p>Klamidia: 1-3 minggu</p>\r\n</li>\r\n<li>\r\n<p>HIV: 2-4 minggu</p>\r\n</li>\r\n<li>\r\n<p>Sifilis: 3-6 minggu</p>\r\n</li>\r\n</ul>\r\n</li>\r\n</ul>\r\n<p><strong>3. Untuk Skrining Rutin</strong></p>\r\n<p>Direkomendasikan bagi:</p>\r\n<ul>\r\n<li>\r\n<p><strong>Pasangan yang akan menikah</strong></p>\r\n</li>\r\n<li>\r\n<p><strong>Ibu hamil</strong><span>&nbsp;</span>(untuk mencegah penularan ke bayi)</p>\r\n</li>\r\n<li>\r\n<p><strong>Pria/Wanita aktif seksual (&gt;1 pasangan dalam 6 bulan)</strong></p>\r\n</li>\r\n<li>\r\n<p><strong>LGBTQ+</strong><span>&nbsp;</span>(risiko tinggi HIV/sifilis)</p>\r\n</li>\r\n</ul>\r\n<p><strong>Paket Skrining Dasar</strong>:</p>\r\n<ul>\r\n<li>\r\n<p>Tes HIV</p>\r\n</li>\r\n<li>\r\n<p>VDRL (sifilis)</p>\r\n</li>\r\n<li>\r\n<p>Swab klamidia/gonore</p>\r\n</li>\r\n<li>\r\n<p>Tes urine lengkap</p>\r\n</li>\r\n</ul>\r\n<p><strong>4. Kondisi Darurat yang Harus Segera Diperiksa</strong></p>\r\n<ul>\r\n<li>\r\n<p>Demam + ruam di telapak tangan/kaki (tanda sifilis stadium 2)</p>\r\n</li>\r\n<li>\r\n<p>Tidak bisa kencing sama sekali (retensi urine)</p>\r\n</li>\r\n<li>\r\n<p>Nyeri perut bawah hebat + demam (PID akut)</p>\r\n</li>\r\n<li>\r\n<p>Reaksi alergi obat IMS</p>\r\n</li>\r\n</ul>\r\n<p><strong>Segera ke IGD jika mengalami gejala di atas!</strong></p>\r\n<p><strong>Proses Pemeriksaan di Klinik Spesialis</strong></p>\r\n<ol>\r\n<li>\r\n<p><strong>Konsultasi Awal</strong></p>\r\n<ul>\r\n<li>\r\n<p>Wawancara medis terperinci</p>\r\n</li>\r\n<li>\r\n<p>Pemeriksaan fisik genital</p>\r\n</li>\r\n</ul>\r\n</li>\r\n<li>\r\n<p><strong>Tes Laboratorium</strong></p>\r\n<ul>\r\n<li>\r\n<p>Darah, urine, atau swab</p>\r\n</li>\r\n<li>\r\n<p>Hasil dalam 1-3 hari</p>\r\n</li>\r\n</ul>\r\n</li>\r\n<li>\r\n<p><strong>Pengobatan</strong></p>\r\n<ul>\r\n<li>\r\n<p>Resep obat sesuai diagnosis</p>\r\n</li>\r\n<li>\r\n<p>Konseling pasangan</p>\r\n</li>\r\n</ul>\r\n</li>\r\n</ol>\r\n<p><strong>Keunggulan Klinik Spesialis</strong>:</p>\r\n<ul>\r\n<li>\r\n<p>Privasi terjamin</p>\r\n</li>\r\n<li>\r\n<p>Dokter berpengalaman</p>\r\n</li>\r\n<li>\r\n<p>Alat diagnostik lengkap</p>\r\n</li>\r\n</ul>\r\n<p><strong>Mit vs Fakta</strong></p>\r\n<p>❌<span>&nbsp;</span><em>\"Tes IMS menyakitkan dan memalukan\"</em><br>✅<span>&nbsp;</span><strong>Fakta</strong>: Prosesnya cepat, sampel bisa diambil sendiri</p>\r\n<p>❌<span>&nbsp;</span><em>\"Jika tidak ada gejala, berarti aman\"</em><br>✅<span>&nbsp;</span><strong>Fakta</strong>: Banyak IMS tidak bergejala tapi bisa menular</p>\r\n<p><strong>Biaya Pemeriksaan</strong></p>\r\n<table>\r\n<tr>\r\n<th>Jenis Tes</th>\r\n<th>Kisaran Harga</th>\r\n</tr>\r\n<tr>\r\n<td>Konsultasi Dokter</td>\r\n<td>Rp150.000-300.000</td>\r\n</tr>\r\n<tr>\r\n<td>Paket Skrining Dasar</td>\r\n<td>Rp500.000-800.000</td>\r\n</tr>\r\n<tr>\r\n<td>Tes HIV</td>\r\n<td>Gratis di Puskesmas</td>\r\n</tr>\r\n</table>\r\n<p><strong>Pesan Dokter</strong></p>\r\n<p><em>\"Jangan biarkan rasa malu menghalangi kesehatan Anda. Lebih baik memeriksakan diri sejak dini daripada menyesal kemudian. Klinik kami menyediakan layanan konsultasi yang nyaman dan profesional.\"</em></p>\r\n<p><strong>Klinik Sanford Medan</strong>: <span>0877-5800-0455</span></p>', 'pngtree-young-stressed-male-patient-consulting-with-doctor-vector-picture-image_2236777.jpg', '2025-04-21 10:06:19'),
(7, '7 Gejala Infeksi Menular Seksual yang Sering Diabaikan', '<p>Infeksi Menular Seksual (IMS) atau Penyakit Menular Seksual (PMS) adalah infeksi yang ditularkan melalui hubungan seksual, baik vaginal, anal, maupun oral. Sayangnya, banyak orang mengabaikan gejala awal IMS karena tidak selalu menimbulkan keluhan yang serius. Padahal, jika tidak ditangani, IMS dapat menyebabkan komplikasi kesehatan yang lebih parah, seperti infertilitas, kerusakan organ, hingga meningkatkan risiko HIV.</p>\r\n<p>Berikut adalah<span>&nbsp;</span><strong>7 gejala IMS yang sering diabaikan</strong><span>&nbsp;</span>namun perlu diwaspadai:</p>\r\n<p><strong>1. Keputihan Tidak Normal</strong></p>\r\n<p>Keputihan bisa menjadi hal yang normal pada wanita, tetapi jika disertai dengan warna kuning kehijauan, bau amis atau busuk, serta gatal, ini bisa menjadi tanda infeksi seperti<span>&nbsp;</span><strong>kandidiasis, trikomoniasis, atau gonore</strong>.</p>\r\n<p><strong>Pendapat Dokter:</strong><br><em>\"Keputihan abnormal sering dianggap sepele, padahal bisa menjadi tanda infeksi bakteri atau parasit. Jika disertai gatal dan bau tidak sedap, segera periksa ke dokter untuk diagnosis yang tepat,\"</em><span>&nbsp;</span>jelas<span>&nbsp;</span><strong>DR. dr. Mohammad Arief EL Habibie, MSM., ISQUA</strong>, Dokter Konsultan Infeksi Menular Seksual (IMS).*</p>\r\n<p><strong>2. Nyeri atau Perih Saat Buang Air Kecil</strong></p>\r\n<p>Nyeri saat buang air kecil bisa disebabkan oleh<span>&nbsp;</span><strong>klamidia, gonore, atau infeksi saluran kemih (ISK)</strong>. Gejala ini sering dikira ISK biasa, padahal bisa jadi tanda IMS.</p>\r\n<p><strong>Pendapat Dokter:</strong><br>*\"Nyeri saat buang air kecil tidak selalu berarti ISK. Pada IMS seperti klamidia, gejala ini sering muncul 1-3 minggu setelah infeksi. Pemeriksaan laboratorium diperlukan untuk memastikannya,\"*<span>&nbsp;</span>kata<span>&nbsp;</span><strong>DR. dr. Mohammad Arief EL Habibie, MSM., ISQUA</strong>.*</p>\r\n<p><strong>3. Ruam atau Luka di Area Kelamin</strong></p>\r\n<p>Munculnya luka, lecet, atau ruam di sekitar kemaluan, anus, atau mulut bisa mengindikasikan<span>&nbsp;</span><strong>herpes genital, sifilis, atau HPV</strong>. Beberapa luka mungkin tidak terasa sakit, sehingga sering diabaikan.</p>\r\n<p><strong>Pendapat Dokter:</strong><br><em>\"Luka tanpa nyeri justru berbahaya karena sering dianggap tidak serius. Sifilis stadium awal bisa muncul sebagai luka kecil yang hilang sendiri, tetapi bakteri tetap aktif dalam tubuh,\"</em><span>&nbsp;</span>ungkap<span>&nbsp;</span><strong>DR. dr. Mohammad Arief EL Habibie, MSM., ISQUA</strong>.*</p>\r\n<p><strong>4. Gatal atau Iritasi di Kelamin</strong></p>\r\n<p>Gatal di area intim bisa disebabkan oleh<span>&nbsp;</span><strong>trikomoniasis, infeksi jamur, atau kudis</strong>. Meski bisa juga karena alergi atau iritasi, jika disertai gejala lain, sebaiknya diperiksa.</p>\r\n<p><strong>Pendapat Dokter:</strong><br><em>\"Gatal yang tidak kunjung membaik dengan obat biasa perlu dicurigai sebagai IMS. Trikomoniasis, misalnya, memerlukan pengobatan antibiotik spesifik,\"</em><span>&nbsp;</span>jelas<span>&nbsp;</span><strong>DR. dr. Mohammad Arief EL Habibie, MSM., ISQUA</strong>.*</p>\r\n<p><strong>5. Nyeri Panggul atau Perut Bawah</strong></p>\r\n<p>Nyeri panggul pada wanita bisa menjadi tanda<span>&nbsp;</span><strong>radang panggul (PID) akibat klamidia atau gonore yang tidak diobati</strong>. Kondisi ini dapat menyebabkan kerusakan tuba falopi dan infertilitas.</p>\r\n<p><strong>Pendapat Dokter:</strong><br><em>\"Nyeri panggul kronis harus dievaluasi lebih lanjut. Infeksi klamidia yang tidak diobati bisa menyebabkan penyumbatan tuba dan kehamilan ektopik,\"</em><span>&nbsp;</span>tegas<span>&nbsp;</span><strong>DR. dr. Mohammad Arief EL Habibie, MSM., ISQUA</strong>.*</p>\r\n<p><strong>6. Pembengkakan Kelenjar Getah Bening</strong></p>\r\n<p>Pembengkakan kelenjar getah bening di selangkangan bisa menandakan infeksi seperti<span>&nbsp;</span><strong>sifilis, herpes, atau HIV</strong>.</p>\r\n<p><strong>Pendapat Dokter:</strong><br><em>\"Kelenjar getah bening yang bengkak tanpa sebab jelas harus diperiksa. Bisa jadi itu respons tubuh terhadap infeksi menular seksual,\"</em><span>&nbsp;</span>kata<span>&nbsp;</span><strong>DR. dr. Mohammad Arief EL Habibie, MSM., ISQUA</strong>.*</p>\r\n<p><strong>7. Pendarahan Tidak Normal</strong></p>\r\n<p>Pendarahan di luar menstruasi atau setelah berhubungan seks bisa menjadi gejala<span>&nbsp;</span><strong>klamidia, gonore, atau kanker serviks akibat HPV</strong>.</p>\r\n<p><strong>Pendapat Dokter:</strong><br><em>\"Pendarahan abnormal adalah tanda bahaya. Wanita yang aktif secara seksual harus rutin melakukan pap smear untuk deteksi dini HPV,\"</em><span>&nbsp;</span>saran<span>&nbsp;</span><strong>DR. dr. Mohammad Arief EL Habibie, MSM., ISQUA</strong>.*</p>\r\n<p><strong>Kapan Harus ke Dokter?</strong></p>\r\n<p>Jika Anda mengalami gejala-gejala di atas, segera konsultasikan ke dokter atau klinik kesehatan reproduksi. Pengobatan dini dapat mencegah komplikasi serius.</p>\r\n<p><strong>Kesimpulan:</strong><br>Banyak gejala IMS yang diabaikan karena dianggap ringan. Padahal, deteksi dan pengobatan sejak dini sangat penting untuk mencegah komplikasi. Selalu gunakan proteksi saat berhubungan seksual dan lakukan tes IMS secara berkala jika aktif secara seksual.</p>\r\n<p><strong>Jangan tunda pemeriksaan&mdash;kesehatan Anda adalah prioritas!</strong></p>\r\n<p><em>Artikel ini telah ditinjau oleh<span>&nbsp;</span><strong>DR. dr. Mohammad Arief EL Habibie, MSM., ISQUA</strong>, Dokter Konsultan Infeksi Menular Seksual (IMS), untuk memastikan keakuratan informasinya.</em></p>\r\n<p>jangan semua nomor ada pendapat dokternya<strong>7 Gejala Infeksi Menular Seksual yang Sering Diabaikan</strong></p>\r\n<p>Infeksi Menular Seksual (IMS) adalah masalah kesehatan global yang seringkali tidak terdeteksi karena banyak penderita mengabaikan gejala awalnya. Padahal, jika tidak ditangani, IMS dapat menyebabkan komplikasi serius seperti infertilitas, kerusakan organ, hingga meningkatkan risiko HIV.</p>\r\n<p>Berikut 7 gejala IMS yang sering diabaikan namun perlu diwaspadai:</p>\r\n<p><strong>1. Keputihan Tidak Normal</strong></p>\r\n<p>Keputihan abnormal dengan warna kuning kehijauan, bau amis/busuk, dan gatal bisa menjadi tanda infeksi seperti trikomoniasis atau gonore.</p>\r\n<p><strong>Pendapat Dokter:</strong><br><em>\"Keputihan abnormal sering dianggap sepele padahal bisa menjadi tanda infeksi serius. Jika disertai bau tidak sedap dan gatal, segera periksakan diri,\"</em><span>&nbsp;</span>jelas DR. dr. Mohammad Arief EL Habibie, MSM., ISQUA, Dokter Konsultan IMS.</p>\r\n<p><strong>2. Nyeri Saat Buang Air Kecil</strong></p>\r\n<p>Nyeri saat berkemih bisa mengindikasikan klamidia atau gonore, bukan hanya infeksi saluran kemih biasa.</p>\r\n<p><strong>3. Luka atau Ruam di Kelamin</strong></p>\r\n<p>Luka tidak nyeri di area genital sering diabaikan, padahal bisa menjadi gejala sifilis atau herpes.</p>\r\n<p><strong>4. Gatal Tak Kunjung Sembuh</strong></p>\r\n<p>Gatal persisten di area intim mungkin menandakan infeksi parasit seperti trikomoniasis.</p>\r\n<p><strong>Pendapat Dokter:</strong><br><em>\"Gatal yang tidak membaik dengan pengobatan biasa perlu dicurigai sebagai IMS dan memerlukan pemeriksaan lebih lanjut,\"</em><span>&nbsp;</span>tambah DR. Arief.</p>\r\n<p><strong>5. Nyeri Panggul Kronis</strong></p>\r\n<p>Pada wanita, nyeri panggul bisa menjadi tanda radang panggul akibat infeksi klamidia yang tidak diobati.</p>\r\n<p><strong>6. Pembengkakan Kelenjar Getah Bening</strong></p>\r\n<p>Pembengkakan kelenjar di selangkangan tanpa sebab jelas patut diwaspadai.</p>\r\n<p><strong>7. Perdarahan Abnormal</strong></p>\r\n<p>Perdarahan di luar menstruasi atau setelah berhubungan intim bisa menjadi tanda infeksi atau komplikasi IMS.</p>\r\n<p><strong>Pentingnya Diagnosis Dini:</strong><br>DR. dr. Mohammad Arief EL Habibie menekankan,<span>&nbsp;</span>*\"Banyak gejala IMS yang samar-samar. Pemeriksaan rutin dan pengobatan tepat waktu sangat penting untuk mencegah komplikasi jangka panjang.\"*</p>\r\n<p><strong>Kesimpulan:</strong><br>Jangan abaikan perubahan sekecil apapun pada tubuh Anda. Gunakan proteksi saat berhubungan seksual dan lakukan pemeriksaan rutin jika aktif secara seksual.</p>\r\n<p><em>Artikel ini telah ditinjau oleh DR. dr. Mohammad Arief EL Habibie, MSM., ISQUA, Dokter Konsultan Infeksi Menular Seksual.</em></p>\r\n<p>tambah lagi keterangan pada 7 nomor ini, minimal 1 paragraf<strong>7 Gejala Infeksi Menular Seksual yang Sering Diabaikan</strong></p>\r\n<p>Infeksi Menular Seksual (IMS) merupakan ancaman kesehatan global yang sering tidak terdiagnosis karena gejala awalnya kerap dianggap remeh. Padahal, data WHO menunjukkan lebih dari 1 juta kasus IMS baru terjadi setiap hari di seluruh dunia. Deteksi dini sangat penting karena banyak IMS yang bisa berkembang menjadi kondisi kronis jika tidak diobati dengan tepat.</p>\r\n<p>Berikut 7 gejala IMS yang sering diabaikan namun berpotensi serius:</p>\r\n<p><strong>1. Keputihan Tidak Normal</strong></p>\r\n<p>Keputihan abnormal merupakan salah satu tanda IMS yang paling umum namun sering dianggap biasa. Perhatikan jika keputihan berubah warna menjadi kuning kehijauan, berbau tajam (amis atau busuk), disertai gatal atau iritasi. Perubahan ini bisa mengindikasikan infeksi seperti trikomoniasis, gonore, atau vaginosis bakterialis. Pada pria, keluarnya cairan abnormal dari penis juga patut diwaspadai.</p>\r\n<p><strong>Pendapat Dokter:</strong><br>*\"Keputihan abnormal sering dianggap sepele padahal bisa menjadi tanda infeksi serius. Jika disertai bau tidak sedap dan gatal yang tidak kunjung membaik dalam 3-5 hari, segera periksakan diri,\"*<span>&nbsp;</span>jelas DR. dr. Mohammad Arief EL Habibie, MSM., ISQUA, Dokter Konsultan IMS.</p>\r\n<p><strong>2. Nyeri Saat Buang Air Kecil</strong></p>\r\n<p>Sensasi panas atau perih saat buang air kecil tidak selalu berarti infeksi saluran kemih biasa. Gejala ini sering muncul pada infeksi klamidia atau gonore, biasanya disertai frekuensi berkemih yang meningkat. Pada kasus tertentu, nyeri mungkin disertai dengan keluarnya nanah dari uretra. Penting dicatat bahwa gejala bisa muncul 1-3 minggu setelah kontak berisiko.</p>\r\n<p><strong>3. Luka atau Ruam di Kelamin</strong></p>\r\n<p>Munculnya luka, lepuh, atau ruam di area genital, anal, atau mulut seringkali tidak disadari karena mungkin tidak menimbulkan nyeri. Luka kecil yang tidak sakit bisa menjadi tanda sifilis stadium awal, sementara lepuh berisi cairan mungkin mengindikasikan herpes genital. Ruam merah bersisik bisa menjadi gejala infeksi jamur atau kudis. Semua kondisi ini memerlukan penanganan medis segera.</p>\r\n<p><strong>4. Gatal Tak Kunjung Sembuh</strong></p>\r\n<p>Gatal persisten di area intim yang tidak membaik dengan pengobatan biasa perlu diwaspadai. Trikomoniasis, infeksi parasit menular seksual, sering menyebabkan gatal hebat disertai iritasi. Infeksi jamur berulang juga bisa menjadi tanda sistem imun yang terganggu akibat IMS lain seperti HIV. Gatal disertai bintik-bintik kecil mungkin mengindikasikan kutu kemaluan (pedikulosis pubis).</p>\r\n<p><strong>Pendapat Dokter:</strong><br><em>\"Gatal genital yang tidak merespon pengobatan antijamur biasa perlu dicurigai sebagai IMS dan memerlukan pemeriksaan mikroskopis serta tes laboratorium,\"</em><span>&nbsp;</span>tambah DR. Arief.</p>\r\n<p><strong>5. Nyeri Panggul Kronis</strong></p>\r\n<p>Pada wanita, nyeri panggul yang menetap bisa menjadi tanda penyakit radang panggul (PID) akibat infeksi klamidia atau gonore yang tidak diobati. Kondisi ini dapat menyebabkan kerusakan permanen pada saluran tuba, meningkatkan risiko kehamilan ektopik dan infertilitas. Nyeri biasanya dirasakan di perut bagian bawah, mungkin disertai demam dan perdarahan tidak teratur.</p>\r\n<p><strong>6. Pembengkakan Kelenjar Getah Bening</strong></p>\r\n<p>Pembesaran kelenjar getah bening di selangkangan tanpa adanya luka atau infeksi kulit yang jelas patut diwaspadai. Limfadenopati inguinalis bisa menjadi respons terhadap infeksi sifilis stadium sekunder, herpes genital, atau infeksi HIV awal. Pembengkakan biasanya tidak nyeri, berukuran &gt;1 cm, dan bertahan lebih dari 4 minggu.</p>\r\n<p><strong>7. Perdarahan Abnormal</strong></p>\r\n<p>Perdarahan di luar siklus menstruasi atau setelah berhubungan intim (perdarahan pasca koitus) merupakan tanda bahaya yang tidak boleh diabaikan. Pada wanita, gejala ini bisa mengindikasikan servisitis akibat klamidia atau gonore, atau bahkan perubahan prakanker akibat infeksi HPV persisten. Pada pria, darah dalam air mani mungkin terkait dengan infeksi prostat.</p>\r\n<p><strong>Pentingnya Diagnosis Dini:</strong><br>DR. dr. Mohammad Arief EL Habibie menekankan,<span>&nbsp;</span><em>\"Sekitar 70% kasus IMS awalnya tidak bergejala atau gejalanya sangat ringan. Pemeriksaan rutin dan pengobatan tepat waktu sangat penting untuk mencegah komplikasi jangka panjang seperti infertilitas, kanker serviks, atau peningkatan kerentanan terhadap HIV.\"</em></p>\r\n<p><strong>Kesimpulan:</strong><br>IMS bukan hanya tentang gejala yang terlihat, tetapi juga tentang konsekuensi kesehatan jangka panjang yang serius. Lakukan pemeriksaan rutin setahun sekali jika aktif secara seksual, atau segera setelah terpapar perilaku berisiko. Penggunaan kondom secara konsisten dan benar tetap menjadi proteksi terbaik.</p>', 'kutil_kelamin2.jpg', '2025-04-22 09:07:03'),
(8, 'Bukan Cuma HIV: 7 Penyakit Kelamin Mematikan yang Jarang Diketahui', '<p>Ketika mendengar tentang penyakit menular seksual (PMS), kebanyakan orang langsung terpikir HIV/AIDS. Padahal, ada banyak infeksi kelamin lain yang sama berbahayanya&mdash;bahkan beberapa bisa menyebabkan kematian dalam hitungan minggu jika tidak diobati!</p>\r\n<p>Berikut adalah<span>&nbsp;</span><strong>7 penyakit kelamin mematikan yang sering luput dari perhatian</strong>, tetapi harus Anda waspadai:</p>\r\n<p><strong>1. Sifilis (Raja Singa) &ndash; Pembunuh Diam-Diam</strong></p>\r\n<p>Sifilis disebabkan oleh bakteri<span>&nbsp;</span><em>Treponema pallidum</em><span>&nbsp;</span>dan dijuluki \"peniru ulung\" karena gejalanya mirip banyak penyakit lain. Jika tidak diobati, sifilis bisa merusak otak, jantung, dan saraf, menyebabkan:</p>\r\n<ul>\r\n<li>\r\n<p><strong>Kelumpuhan</strong></p>\r\n</li>\r\n<li>\r\n<p><strong>Demensia</strong></p>\r\n</li>\r\n<li>\r\n<p><strong>Kematian mendadak</strong></p>\r\n</li>\r\n</ul>\r\n<p><strong>Fakta Mengerikan:</strong><span>&nbsp;</span>Sifilis kongenital bisa membunuh bayi dalam kandungan atau menyebabkan cacat lahir parah.</p>\r\n<p><strong>2. Gonore (Kencing Nanah) yang Kebal Antibiotik</strong></p>\r\n<p>Gonore semakin sulit diobati karena munculnya strain<span>&nbsp;</span><strong>superbug yang resisten terhadap antibiotik</strong>. Komplikasinya termasuk:</p>\r\n<ul>\r\n<li>\r\n<p><strong>Infeksi darah (sepsis)</strong></p>\r\n</li>\r\n<li>\r\n<p><strong>Kemandulan permanen</strong></p>\r\n</li>\r\n<li>\r\n<p><strong>Radang sendi destruktif</strong></p>\r\n</li>\r\n</ul>\r\n<p><strong>Kasus Terbaru:</strong><span>&nbsp;</span>WHO menemukan strain gonore \"XXDR\" yang hampir tidak bisa diobati di Asia Tenggara.</p>\r\n<p><strong>3. Klamidia &ndash; Penyebab Diam-Diam Kemandulan Wanita</strong></p>\r\n<p>Sering tanpa gejala, klamidia diam-diam merusak saluran tuba, menyebabkan:</p>\r\n<ul>\r\n<li>\r\n<p><strong>Kehamilan ektopik (berakibat kematian)</strong></p>\r\n</li>\r\n<li>\r\n<p><strong>Penyakit radang panggul (PID)</strong></p>\r\n</li>\r\n<li>\r\n<p><strong>Kemandulan tanpa gejala</strong></p>\r\n</li>\r\n</ul>\r\n<p><strong>Statistik Menakutkan:</strong><span>&nbsp;</span>50% pria dan 70% wanita tidak menyadari terinfeksi!</p>\r\n<p><strong>4. Hepatitis B &amp; C &ndash; Pembunuh Hati Senyap</strong></p>\r\n<p>Ditularkan lewat hubungan intim, hepatitis B &amp; C menyebabkan:</p>\r\n<ul>\r\n<li>\r\n<p><strong>Sirosis hati</strong></p>\r\n</li>\r\n<li>\r\n<p><strong>Kanker hati</strong></p>\r\n</li>\r\n<li>\r\n<p><strong>Gagal hati akut</strong></p>\r\n</li>\r\n</ul>\r\n<p><strong>Fakta Mengejutkan:</strong><span>&nbsp;</span>Hepatitis B 100x lebih mudah menular daripada HIV!</p>\r\n<p><strong>5. Herpes Genital &ndash; Infeksi Seumur Hidup yang Mematikan Bayi</strong></p>\r\n<p>Virus herpes simplex (HSV) tidak bisa disembuhkan dan bisa:</p>\r\n<ul>\r\n<li>\r\n<p><strong>Menyerang otak (ensefalitis herpes)</strong></p>\r\n</li>\r\n<li>\r\n<p><strong>Membunuh bayi baru lahir (herpes neonatal)</strong></p>\r\n</li>\r\n<li>\r\n<p><strong>Meningkatkan risiko HIV 3x lipat</strong></p>\r\n</li>\r\n</ul>\r\n<p><strong>Data Kemenkes:</strong><span>&nbsp;</span>20% orang dewasa di Indonesia positif HSV-2 tanpa gejala.</p>\r\n<p><strong>6. Chancroid &ndash; Luka Kelamin yang Memicu HIV</strong></p>\r\n<p>Disebabkan bakteri<span>&nbsp;</span><em>Haemophilus ducreyi</em>, chancroid menyebabkan:</p>\r\n<ul>\r\n<li>\r\n<p><strong>Luka bernanah yang sangat sakit</strong></p>\r\n</li>\r\n<li>\r\n<p><strong>Pembengkakan kelenjar getah bening pecah</strong></p>\r\n</li>\r\n<li>\r\n<p><strong>Meningkatkan penularan HIV hingga 10x</strong></p>\r\n</li>\r\n</ul>\r\n<p><strong>Kasus Langka Tapi Nyata:</strong><span>&nbsp;</span>Masih ditemukan di daerah dengan sanitasi buruk.</p>\r\n<p><strong>7. Lymphogranuloma Venereum (LGV) &ndash; Penyakit Kelamin Pemakan Daging</strong></p>\r\n<p>Bentuk agresif dari klamidia ini menyebabkan:</p>\r\n<ul>\r\n<li>\r\n<p><strong>Borok kelamin dalam</strong></p>\r\n</li>\r\n<li>\r\n<p><strong>Pembengkakan kelenjar getah bening pecah</strong></p>\r\n</li>\r\n<li>\r\n<p><strong>Kerusakan rektum permanen</strong></p>\r\n</li>\r\n</ul>\r\n<p><strong>Wabah Terkini:</strong><span>&nbsp;</span>Meledak di antara pria seks dengan pria di Eropa dan Amerika.</p>\r\n<p><strong>Kapan Harus ke Dokter?</strong></p>\r\n<p>Segera periksa jika Anda mengalami:<br>✅ Luka/ruam di kelamin<br>✅ Nyeri saat kencing atau berhubungan<br>✅ Keluar nanah/darah dari kemaluan<br>✅ Pembengkakan kelenjar di selangkangan</p>\r\n<p><strong>Peringatan Dokter:</strong><br><em>\"Banyak penyakit kelamin ini awalnya tanpa gejala, tapi ketika muncul komplikasi, sudah terlambat. Skrining rutin adalah kunci penyelamatan nyawa,\"</em><span>&nbsp;</span>tegas&nbsp;DR.dr. Mohammad Arief EL Habibie, MSM., ISQUA, Dokter Konsultan Infeksi Menular Seksual (IMS).</p>\r\n<p><strong>Lindungi Diri Anda!</strong></p>\r\n<ul>\r\n<li>\r\n<p>Gunakan kondom<span>&nbsp;</span><strong>setiap kali</strong><span>&nbsp;</span>berhubungan</p>\r\n</li>\r\n<li>\r\n<p>Lakukan tes IMS<span>&nbsp;</span><strong>rutin 6 bulan sekali</strong><span>&nbsp;</span>jika aktif seksual</p>\r\n</li>\r\n<li>\r\n<p>Vaksinasi Hepatitis B &amp; HPV</p>\r\n</li>\r\n</ul>\r\n<p>Jangan remehkan penyakit kelamin&mdash;beberapa bisa membunuh diam-diam sebelum Anda sadar!</p>', 'iStock-1168519376-800x450.jpg', '2025-04-22 12:36:03'),
(9, 'Waspada! 5 Penyakit Kelamin yang Bisa Merusak Organ Reproduksi Permanen', '<p>Penyakit menular seksual (PMS) tidak hanya mengganggu kenyamanan, tetapi beberapa di antaranya dapat menyebabkan kerusakan permanen pada sistem reproduksi. Yang mengkhawatirkan, banyak dari penyakit ini sering tidak menunjukkan gejala awal, sehingga penderita baru menyadari ketika kerusakan sudah terjadi.</p>\r\n<p>Berikut adalah 5 penyakit kelamin paling berbahaya yang dapat merusak organ reproduksi secara permanen:</p>\r\n<p><strong>1. Klamidia - Silent Destroyer Kesuburan</strong></p>\r\n<p><strong>Mekanisme Kerusakan:</strong></p>\r\n<ul>\r\n<li>\r\n<p>Menyebabkan penyumbatan tuba falopi pada wanita</p>\r\n</li>\r\n<li>\r\n<p>Memicu epididimitis (radang saluran sperma) pada pria</p>\r\n</li>\r\n<li>\r\n<p>Menyebabkan jaringan parut di organ reproduksi</p>\r\n</li>\r\n</ul>\r\n<p><strong>Fakta Mengerikan:</strong></p>\r\n<ul>\r\n<li>\r\n<p>50% wanita yang terinfeksi klamidia tidak menyadari gejalanya</p>\r\n</li>\r\n<li>\r\n<p>Dapat menyebabkan kemandulan setelah 6-12 bulan infeksi</p>\r\n</li>\r\n</ul>\r\n<p><strong>2. Gonore (Kencing Nanah) - Perusak Multi Organ</strong></p>\r\n<p><strong>Dampak Permanen:</strong></p>\r\n<ul>\r\n<li>\r\n<p>Pada wanita: Menyebabkan penyakit radang panggul (PID)</p>\r\n</li>\r\n<li>\r\n<p>Pada pria: Menyumbat saluran sperma</p>\r\n</li>\r\n<li>\r\n<p>Pada keduanya: Meningkatkan risiko kehamilan ektopik</p>\r\n</li>\r\n</ul>\r\n<p><strong>Krisis Global:</strong></p>\r\n<ul>\r\n<li>\r\n<p>Munculnya strain gonore super yang kebal antibiotik</p>\r\n</li>\r\n<li>\r\n<p>Angka resistensi antibiotik mencapai 78% di Asia Tenggara</p>\r\n</li>\r\n</ul>\r\n<p><strong>3. Sifilis - The Great Imitator</strong></p>\r\n<p><strong>Kerusakan Jangka Panjang:</strong></p>\r\n<ul>\r\n<li>\r\n<p>Fase tersier dapat merusak seluruh sistem reproduksi</p>\r\n</li>\r\n<li>\r\n<p>Menyebabkan keguguran berulang pada wanita hamil</p>\r\n</li>\r\n<li>\r\n<p>Meningkatkan risiko bayi lahir cacat hingga 40%</p>\r\n</li>\r\n</ul>\r\n<p><strong>Statistik Mengejutkan:</strong></p>\r\n<ul>\r\n<li>\r\n<p>Kasus sifilis kongenital meningkat 300% dalam 5 tahun terakhir</p>\r\n</li>\r\n</ul>\r\n<p><strong>4. Mycoplasma Genitalium - Ancaman Baru</strong></p>\r\n<p><strong>Efek Destruktif:</strong></p>\r\n<ul>\r\n<li>\r\n<p>Menyebabkan uretritis kronis</p>\r\n</li>\r\n<li>\r\n<p>Memicu endometritis (radang rahim)</p>\r\n</li>\r\n<li>\r\n<p>Berhubungan dengan kelahiran prematur</p>\r\n</li>\r\n</ul>\r\n<p><strong>Tantangan Medis:</strong></p>\r\n<ul>\r\n<li>\r\n<p>60% kasus menunjukkan resistensi antibiotik</p>\r\n</li>\r\n<li>\r\n<p>Tes diagnostik masih sulit diakses</p>\r\n</li>\r\n</ul>\r\n<p><strong>5. Trichomoniasis - Perusak Jaringan Halus</strong></p>\r\n<p><strong>Dampak Permanen:</strong></p>\r\n<ul>\r\n<li>\r\n<p>Menyebabkan servisitis kronis</p>\r\n</li>\r\n<li>\r\n<p>Meningkatkan risiko persalinan prematur</p>\r\n</li>\r\n<li>\r\n<p>Mempercepat penularan HIV</p>\r\n</li>\r\n</ul>\r\n<p><strong>Fakta yang Diabaikan:</strong></p>\r\n<ul>\r\n<li>\r\n<p>70% penderita tidak menunjukkan gejala awal</p>\r\n</li>\r\n<li>\r\n<p>Dapat bertahan selama bertahun-tahun tanpa pengobatan</p>\r\n</li>\r\n</ul>\r\n<p><strong>Tanda Peringatan Dini</strong></p>\r\n<p>Waspadai gejala berikut:</p>\r\n<ul>\r\n<li>\r\n<p>Nyeri panggul kronis</p>\r\n</li>\r\n<li>\r\n<p>Perdarahan tidak teratur</p>\r\n</li>\r\n<li>\r\n<p>Nyeri saat berhubungan</p>\r\n</li>\r\n<li>\r\n<p>Keluar cairan abnormal</p>\r\n</li>\r\n<li>\r\n<p>Gatal atau iritasi berkepanjangan</p>\r\n</li>\r\n</ul>\r\n<p><strong>Rekomendasi Dokter:</strong><br>\"Lakukan skrining rutin setiap 6 bulan jika aktif secara seksual. Deteksi dini adalah satu-satunya cara mencegah kerusakan permanen,\" tegas&nbsp;DR.dr. Mohammad Arief EL Habibie, MSM., ISQUA, Dokter Konsultan Infeksi Menular Seksual (IMS).</p>\r\n<p><strong>Langkah Pencegahan Efektif</strong></p>\r\n<ol>\r\n<li>\r\n<p>Gunakan proteksi barrier (kondom) secara konsisten</p>\r\n</li>\r\n<li>\r\n<p>Batasi jumlah pasangan seksual</p>\r\n</li>\r\n<li>\r\n<p>Lakukan vaksinasi HPV dan Hepatitis B</p>\r\n</li>\r\n<li>\r\n<p>Hindari douching yang mengganggu flora normal</p>\r\n</li>\r\n<li>\r\n<p>Segera periksakan diri jika ada gejala mencurigakan</p>\r\n</li>\r\n</ol>\r\n<p><strong>Pesan Penting:</strong><br>Kerusakan organ reproduksi akibat PMS seringkali tidak dapat diperbaiki. Jangan tunggu sampai muncul komplikasi untuk memeriksakan diri. Kesuburan Anda adalah investasi jangka panjang yang perlu dilindungi sejak dini.</p>', 'optimg-medium---infeksi-saluran-kemih-1.jpeg', '2025-04-21 09:02:35'),
(10, 'Kutil Kelamin vs Herpes: Bagaimana Membedakannya?', '<p><span><strong>Panduan Medis oleh Dokter Spesialis</strong></span></p>\r\n<p><span><em>(Ditinjau oleh: DR. dr. Mohammad Arief EL Habibie, MSM., ISQUA - Dokter Konsultan Infeksi Menular Seksual)</em></span></p>\r\n<p><span><strong>Pendahuluan</strong></span></p>\r\n<p><span>Kutil kelamin dan herpes genital adalah dua&nbsp;<strong>Infeksi Menular Seksual (IMS)</strong>&nbsp;yang sering disalahartikan karena sama-sama menyerang area genital. Padahal, keduanya memiliki penyebab, gejala, dan penanganan yang berbeda.</span></p>\r\n<p><span><strong>DR. dr. Mohammad Arief EL Habibie</strong>&nbsp;memaparkan:</span><br><span><em>\"60% pasien mengira herpes adalah kutil, atau sebaliknya. Kesalahan diagnosis bisa berakibat fatal karena pengobatannya berbeda.\"</em></span></p>\r\n<p><span><strong>Perbedaan Mendasar</strong></span></p>\r\n<table>\r\n<tr>\r\n<th><span>Karakteristik</span></th>\r\n<th><span><strong>Kutil Kelamin</strong>&nbsp;(<em>Genital Warts</em>)</span></th>\r\n<th><span><strong>Herpes Genital</strong>&nbsp;(<em>HSV-2</em>)</span></th>\r\n</tr>\r\n<tr>\r\n<td><span><strong>Penyebab</strong></span></td>\r\n<td><span>Virus HPV (Tipe 6 &amp; 11)</span></td>\r\n<td><span>Virus Herpes Simplex (HSV-2)</span></td>\r\n</tr>\r\n<tr>\r\n<td><span><strong>Gejala</strong></span></td>\r\n<td><span>Benjolan keras seperti kembang kol</span></td>\r\n<td><span>Lembing berisi cairan yang pecah jadi luka</span></td>\r\n</tr>\r\n<tr>\r\n<td><span><strong>Nyeri</strong></span></td>\r\n<td><span>Umumnya tidak nyeri</span></td>\r\n<td><span>Sangat nyeri seperti terbakar</span></td>\r\n</tr>\r\n<tr>\r\n<td><span><strong>Penularan</strong></span></td>\r\n<td><span>Kontak kulit-genital</span></td>\r\n<td><span>Seksual &amp; cairan tubuh (bahkan tanpa gejala)</span></td>\r\n</tr>\r\n<tr>\r\n<td><span><strong>Risiko Kanker</strong></span></td>\r\n<td><span>Ya (HPV tipe 16/18)</span></td>\r\n<td><span>Tidak</span></td>\r\n</tr>\r\n</table>\r\n<p><span><strong>Cara Membedakan dari Gejala Fisik</strong></span></p>\r\n<p><span><strong>1. Kutil Kelamin</strong></span></p>\r\n<ul>\r\n<li>\r\n<p><span><strong>Tampilan</strong>:</span></p>\r\n<ul>\r\n<li>\r\n<p><span>Benjolan kecil, permukaan kasar</span></p>\r\n</li>\r\n<li>\r\n<p><span>Warna kulit atau keabuan</span></p>\r\n</li>\r\n<li>\r\n<p><span>Tumbuh berkelompok (seperti kembang kol)</span></p>\r\n</li>\r\n</ul>\r\n</li>\r\n<li>\r\n<p><span><strong>Lokasi</strong>:</span></p>\r\n<ul>\r\n<li>\r\n<p><span>Penis, vulva, anus, atau mulut</span></p>\r\n</li>\r\n</ul>\r\n</li>\r\n<li>\r\n<p><span><strong>Ciri Khas</strong>:</span></p>\r\n<ul>\r\n<li>\r\n<p><span><strong>Tidak sakit</strong> kecuali tergesek</span></p>\r\n</li>\r\n</ul>\r\n</li>\r\n</ul>\r\n<p><strong>2. Herpes Genital</strong></p>\r\n<ul>\r\n<li>\r\n<p><strong>Tampilan</strong>:</p>\r\n<ul>\r\n<li>\r\n<p>Lepuh kecil berisi cairan</p>\r\n</li>\r\n<li>\r\n<p>Pecah menjadi luka terbuka</p>\r\n</li>\r\n<li>\r\n<p>Kulit sekitar merah meradang</p>\r\n</li>\r\n</ul>\r\n</li>\r\n<li>\r\n<p><strong>Lokasi</strong>:</p>\r\n<ul>\r\n<li>\r\n<p>Alat genital, bokong, atau paha</p>\r\n</li>\r\n</ul>\r\n</li>\r\n<li>\r\n<p><strong>Ciri Khas</strong>:</p>\r\n<ul>\r\n<li>\r\n<p><strong>Nyeri hebat</strong>, gatal, dan demam saat pertama kali terinfeksi</p>\r\n</li>\r\n</ul>\r\n</li>\r\n</ul>\r\n<p><strong>Diagnosis Medis</strong></p>\r\n<p>Menurut&nbsp;<strong>DR. Arief</strong>, pemeriksaan wajib meliputi:</p>\r\n<ol>\r\n<li>\r\n<p><strong>Tes Visual</strong>: Dokter memeriksa lesi.</p>\r\n</li>\r\n<li>\r\n<p><strong>PCR Swab</strong>: Ambil sampel dari luka untuk deteksi HSV/HPV.</p>\r\n</li>\r\n<li>\r\n<p><strong>Tes Darah</strong>: Cari antibodi HSV (untuk herpes).</p>\r\n</li>\r\n</ol>\r\n<p><em>\"Herpes bisa didiagnosis bahkan saat tidak ada gejala, sedangkan kutil kelamin lebih mudah dikenali secara visual,\"</em>&nbsp;tambahnya.</p>\r\n<p><strong>Pengobatan yang Berbeda</strong><strong>Kutil Kelamin</strong></p>\r\n<ul>\r\n<li>\r\n<p><strong>Obat</strong>: Krim Imiquimod, Podofiloks.</p>\r\n</li>\r\n<li>\r\n<p><strong>Prosedur</strong>: Krioterapi, laser, atau operasi.</p>\r\n</li>\r\n<li>\r\n<p><strong>Vaksin</strong>: Gardasil untuk pencegahan.</p>\r\n</li>\r\n</ul>\r\n<p><strong>Herpes Genital</strong></p>\r\n<ul>\r\n<li>\r\n<p><strong>Obat</strong>: Antiviral (Acyclovir, Valacyclovir).</p>\r\n</li>\r\n<li>\r\n<p><strong>Manajemen</strong>: Obat diminum saat kambuh.</p>\r\n</li>\r\n<li>\r\n<p><strong>Fakta</strong>:&nbsp;<strong>Tidak bisa sembuh total</strong>&nbsp;&ndash; virus tetap dormant di saraf.</p>\r\n</li>\r\n</ul>\r\n<p><strong>Pencegahan</strong></p>\r\n<table>\r\n<tr>\r\n<th><strong>Kutil Kelamin</strong></th>\r\n<th><strong>Herpes Genital</strong></th>\r\n</tr>\r\n<tr>\r\n<td>✔️ Vaksin HPV</td>\r\n<td>❌ Tidak ada vaksin</td>\r\n</tr>\r\n<tr>\r\n<td>✔️ Kondom (70% efektif)</td>\r\n<td>✔️ Kondom (kurangi risiko 50%)</td>\r\n</tr>\r\n<tr>\r\n<td>❌ Tidak menular tanpa gejala</td>\r\n<td>✔️ Bisa menular meski tanpa gejala</td>\r\n</tr>\r\n</table>\r\n<p><strong>Kapan Harus ke Dokter?</strong></p>\r\n<p>Segera konsultasi jika:</p>\r\n<ul>\r\n<li>\r\n<p>Ada benjolan/luka di genital yang tidak hilang dalam 1 minggu.</p>\r\n</li>\r\n<li>\r\n<p>Nyeri saat buang air kecil atau berhubungan seks.</p>\r\n</li>\r\n<li>\r\n<p>Pasangan terdiagnosis HPV/Herpes.</p>\r\n</li>\r\n</ul>\r\n<p data-start=\"3919\" data-end=\"3949\"><strong data-start=\"3919\" data-end=\"3949\">Untuk konsultasi, hubungi:</strong></p>\r\n<ul data-start=\"3950\" data-end=\"4029\">\r\n<li data-start=\"3950\" data-end=\"3983\">\r\n<p data-start=\"3952\" data-end=\"3983\"><strong data-start=\"3952\" data-end=\"3981\">Klinik Sanford : 0877-5800-0455</strong></p>\r\n</li>\r\n</ul>\r\n<p><strong>Kesimpulan</strong></p>\r\n<ul>\r\n<li>\r\n<p><strong>Kutil kelamin</strong>&nbsp;= Benjolan tidak nyeri, risiko kanker.</p>\r\n</li>\r\n<li>\r\n<p><strong>Herpes</strong>&nbsp;= Lembing nyeri, kambuhan seumur hidup.</p>\r\n</li>\r\n</ul>\r\n<p><strong>Pesan Dokter</strong>:<br><em>\"Jangan self-diagnosis! Salah obat bisa memperparah kondisi. Segera periksa ke klinik IMS terdekat.\"</em></p>\r\n<p><strong>Artikel Terkait</strong>:</p>\r\n<ul>\r\n<li>\r\n<p><a>Benarkah Herpes Genital Tidak Bisa Sembuh Total?</a></p>\r\n</li>\r\n<li>\r\n<p><a>Vaksin HPV: Perlukah untuk Pria?</a></p>\r\n</li>\r\n</ul>\r\n<p><em>(Artikel ini telah direview oleh DR. dr. Mohammad Arief EL Habibie, MSM., ISQUA)</em></p>', 'gr7.jpeg', '2025-04-25 09:55:59');
INSERT INTO `artikel` (`id`, `judul`, `isi`, `gambar`, `tanggal`) VALUES
(11, 'Waspada Virus HPV! Ini 3 Cara Penularan yang Tak Disadari', '<p data-start=\"195\" data-end=\"403\">Virus HPV atau <strong data-start=\"210\" data-end=\"234\">Human Papillomavirus</strong> selama ini dikenal luas sebagai penyebab utama kanker serviks. Namun, tahukah Anda bahwa virus ini bisa menular dengan cara-cara yang kerap tidak disadari banyak orang?</p>\r\n<p data-start=\"405\" data-end=\"611\">Menurut pakar kesehatan, HPV bukan hanya soal kontak seksual semata. Ada beberapa jalur penularan lain yang perlu diwaspadai, apalagi karena banyak kasus infeksi HPV tidak menimbulkan gejala apapun di awal.</p>\r\n<p data-start=\"613\" data-end=\"679\">Berikut tiga cara penularan HPV yang kerap terjadi tanpa disadari:</p>\r\n<p><span><strong>1. Kontak Kulit ke Kulit</strong></span></p>\r\n<p data-start=\"715\" data-end=\"977\">Salah satu jalur utama penularan HPV adalah melalui <strong data-start=\"767\" data-end=\"792\">kontak kulit ke kulit</strong>, bukan hanya lewat hubungan seksual penetratif.<br data-start=\"840\" data-end=\"843\">Cukup dengan adanya <strong data-start=\"863\" data-end=\"880\">gesekan kulit</strong> dengan area tubuh yang terinfeksi, virus bisa berpindah. Itu sebabnya, HPV bisa menular melalui:</p>\r\n<ul data-start=\"979\" data-end=\"1083\">\r\n<li data-start=\"979\" data-end=\"1027\">\r\n<p data-start=\"981\" data-end=\"1027\">Sentuhan intim tanpa hubungan seksual lengkap,</p>\r\n</li>\r\n<li data-start=\"1028\" data-end=\"1083\">\r\n<p data-start=\"1030\" data-end=\"1083\">Sentuhan di area genital, anus, mulut, bahkan tangan.</p>\r\n</li>\r\n</ul>\r\n<p data-start=\"1087\" data-end=\"1263\">&ldquo;Banyak yang mengira tanpa hubungan seksual, risikonya nol. Padahal, hanya dengan sentuhan intim, virus sudah bisa berpindah,&rdquo; jelas Dr. Mohammad Arief El Habibie, MSM., ISQUA.</p>\r\n<p><span><strong>2. Berbagi Barang Pribadi</strong></span></p>\r\n<p data-start=\"1300\" data-end=\"1479\">Meski lebih jarang, penggunaan <strong data-start=\"1331\" data-end=\"1367\">barang pribadi secara bergantian</strong> dengan orang yang terinfeksi bisa berpotensi menularkan HPV, terutama jika ada luka terbuka atau kulit iritasi.</p>\r\n<p data-start=\"1481\" data-end=\"1548\">Barang-barang yang sebaiknya <strong data-start=\"1510\" data-end=\"1535\">tidak dipakai bersama</strong> antara lain:</p>\r\n<ul data-start=\"1550\" data-end=\"1608\">\r\n<li data-start=\"1550\" data-end=\"1559\">\r\n<p data-start=\"1552\" data-end=\"1559\">Handuk,</p>\r\n</li>\r\n<li data-start=\"1560\" data-end=\"1576\">\r\n<p data-start=\"1562\" data-end=\"1576\">Pakaian dalam,</p>\r\n</li>\r\n<li data-start=\"1577\" data-end=\"1590\">\r\n<p data-start=\"1579\" data-end=\"1590\">Alat cukur,</p>\r\n</li>\r\n<li data-start=\"1591\" data-end=\"1608\">\r\n<p data-start=\"1593\" data-end=\"1608\">Sabun batangan.</p>\r\n</li>\r\n</ul>\r\n<p data-start=\"1610\" data-end=\"1768\">Meskipun penularan melalui media ini tidak seefektif kontak kulit langsung, tetap disarankan untuk menjaga kebersihan dan tidak berbagi barang-barang pribadi.</p>\r\n<p><span><strong>3. Dari Ibu ke Bayi saat Persalinan</strong></span></p>\r\n<p data-start=\"1815\" data-end=\"2062\">Penularan HPV juga bisa terjadi dari <strong data-start=\"1852\" data-end=\"1890\">ibu yang terinfeksi kepada bayinya</strong> saat proses kelahiran normal.<br data-start=\"1920\" data-end=\"1923\">Bayi yang terpapar HPV berisiko mengalami kondisi langka seperti <strong data-start=\"1988\" data-end=\"2016\">papillomatosis laringeal</strong>, yaitu tumbuhnya kutil di saluran pernapasan.</p>\r\n<p data-start=\"2064\" data-end=\"2209\">Oleh karena itu, ibu hamil yang diketahui mengidap HPV sebaiknya berdiskusi dengan dokter mengenai metode persalinan yang paling aman untuk bayi.</p>\r\n<p>Pencegahan adalah Kunci</p>\r\n<p data-start=\"2243\" data-end=\"2415\">Menggunakan pengaman saat berhubungan intim, menjaga kebersihan diri, tidak berbagi barang pribadi, dan vaksinasi HPV adalah langkah-langkah efektif untuk mencegah infeksi.</p>\r\n<p data-start=\"2419\" data-end=\"2540\">\"Vaksin HPV saat ini menjadi salah satu alat pencegahan kanker serviks paling efektif yang kita miliki,\" tegas Dr. Arief.</p>\r\n<p data-start=\"2542\" data-end=\"2639\">Vaksinasi dianjurkan sejak usia remaja, sebelum aktif secara seksual, untuk perlindungan optimal.</p>\r\n<p><span><strong>Kesimpulan</strong></span></p>\r\n<p data-start=\"2660\" data-end=\"2946\">HPV bisa menyerang siapa saja, kapan saja, bahkan melalui cara-cara yang tak kita duga. Mengenali jalur-jalur penularan ini bisa menjadi langkah pertama untuk melindungi diri sendiri dan orang-orang tercinta.<br data-start=\"2868\" data-end=\"2871\">Karena dalam dunia kesehatan, <strong data-start=\"2901\" data-end=\"2946\">kesadaran lebih baik daripada penyesalan.</strong></p>', 'Ilustrasi-Penyebab-HPV-1024x576.jpg', '2025-04-25 09:55:44');

